// ===================================
// BASEMAP
// ===================================
// Basemap pakai OpenFreeMap - gratis, tanpa API key, tampilan bagus
// URL tiles per basemap - kita hanya ganti tiles, bukan seluruh style
// Dengan cara ini layer data kita tidak pernah hilang saat ganti basemap
const basemapTiles = {
    street   : 'https://basemap.mapid.io/styles/street-2d-building/style.json?key=69a8edeffdb1d3dbc8b3022c',
    dark     : 'https://basemap.mapid.io/styles/dark/style.json?key=69a8edeffdb1d3dbc8b3022c',
    satellite: 'https://basemap.mapid.io/styles/satellite/style.json?key=69a8edeffdb1d3dbc8b3022c',
};

// Style awal pakai MAPID Street
const basemapStreet    = basemapTiles.street;
const basemapDark      = basemapTiles.dark;
const basemapSatellite = basemapTiles.satellite;

// ===================================
// INISIALISASI MAP
// ===================================
const map = new maplibregl.Map({
    container: 'map',
    style    : basemapStreet,
    center   : [110.4103, -7.0051],
    zoom     : 11
});

map.addControl(new maplibregl.NavigationControl(), 'top-right');

// Handle missing sprites/images dari MAPID
// Tanpa ini, missing image bisa menyebabkan layer tidak render
map.on('styleimagemissing', (e) => {
    console.warn('Missing image:', e.id, '- adding empty placeholder');
    // Tambah placeholder 1x1 pixel transparan supaya render tidak terblokir
    const emptyImage = { width: 1, height: 1, data: new Uint8Array(4) };
    map.addImage(e.id, emptyImage);
});

// Error handler - jika basemap gagal load, coba fallback
map.on('error', (e) => {
    console.warn('Map error:', e);
    // Jika style gagal load, pakai MapLibre demo tiles sebagai fallback
    if (e.error && e.error.status === 404) {
        console.warn('Style 404 - switching to fallback basemap...');
        map.setStyle(basemapFallback);
    }
});

