// ===================================
// VARIABEL GLOBAL
// ===================================
const dataFasilitas = {
    rs: null, puskesmas: null, klinik: null, apotek: null, drg: null
};

const kategoriConfig = {
    rs        : { warna: '#ef4444', label: 'Rumah Sakit', icon: '🏥', layer: 'rs-layer',       source: 'rs'        },
    puskesmas : { warna: '#22c55e', label: 'Puskesmas',   icon: '🏢', layer: 'puskesmas-layer', source: 'puskesmas' },
    klinik    : { warna: '#3b82f6', label: 'Klinik',      icon: '🏨', layer: 'klinik-layer',    source: 'klinik'    },
    apotek    : { warna: '#a855f7', label: 'Apotek',       icon: '💊', layer: 'apotek-layer',    source: 'apotek'    },
    drg       : { warna: '#f97316', label: 'Dokter Gigi', icon: '🦷', layer: 'drg-layer',       source: 'drg'       },
};

const kecepatanTransportasi = {
    motorcycle: 500, car: 700,
};

let lokasiUser = null;
let markerUser = null;

// ===================================
// STATE TOGGLE - simpan visibility setiap layer
// Dipakai untuk restore setelah ganti basemap
// ===================================
const toggleState = {
    'kecamatan-layer' : 'visible',
    'jalan-layer'     : 'visible',
    'rs-layer'        : 'visible',
    'puskesmas-layer' : 'visible',
    'klinik-layer'    : 'visible',
    'apotek-layer'    : 'visible',
    'drg-layer'       : 'visible',
};

// ===================================
// LOAD DATA - langsung dari variabel offline, tidak ada fetch!
// ===================================
// Hanya pakai style.load - dipanggil saat pertama load DAN saat ganti basemap
// Tidak pakai map.on load karena akan conflict dengan style.load
// style.load pertama kali saat peta dibuka
map.on('style.load', () => {
    console.log('style.load pertama - load semua data...');
    loadKecamatan();
    loadJalan();
    loadSemuaFasilitas(true);
});

function loadAllData(isFirst = false) {
    loadKecamatan();
    loadJalan();
    loadSemuaFasilitas(isFirst);
}

// Restore visibility state setelah semua layer di-rebuild
function restoreToggleState() {
    // Delay 200ms supaya semua layer benar-benar sudah ter-add ke peta
    // sebelum kita set visibility-nya
    setTimeout(() => {
        Object.entries(toggleState).forEach(([layerId, visibility]) => {
            if (map.getLayer(layerId)) {
                map.setLayoutProperty(layerId, 'visibility', visibility);
            }
            // Sync juga layer tambahan kecamatan
            if (layerId === 'kecamatan-layer') {
                ['kecamatan-line-layer', 'kecamatan-label-layer'].forEach(id => {
                    if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visibility);
                });
            }
        });
        // Sync tombol toggle di sidebar
        syncToggleButtons();
        console.log('Toggle state restored:', toggleState);
    }, 200);
}

// Sinkronkan ikon tombol toggle dengan state yang tersimpan
function syncToggleButtons() {
    const mapping = {
        'rs-layer'       : 'btn-rs',
        'puskesmas-layer': 'btn-puskesmas',
        'klinik-layer'   : 'btn-klinik',
        'apotek-layer'   : 'btn-apotek',
        'drg-layer'      : 'btn-drg',
        'jalan-layer'    : 'btn-jalan',
        'kecamatan-layer': 'btn-kecamatan',
    };
    Object.entries(mapping).forEach(([layerId, btnId]) => {
        const btn = document.getElementById(btnId);
        if (!btn) return;
        const isVisible = toggleState[layerId] === 'visible';
        btn.textContent = isVisible ? '👁' : '🚫';
        btn.classList.toggle('off', !isVisible);
    });
}

// ===================================
// KECAMATAN
// ===================================
function loadKecamatan() {
    const data = dataOffline.kecamatan;
    console.log('kecamatanData', data);

    // Tambah source jika belum ada
    if (!map.getSource('kecamatan')) {
        map.addSource('kecamatan', { type: 'geojson', data });
    } else {
        map.getSource('kecamatan').setData(data);
    }

    // Tambah layer jika belum ada
    if (!map.getLayer('kecamatan-layer')) {
        map.addLayer({
            id: 'kecamatan-layer', source: 'kecamatan', type: 'fill',
            paint: { 'fill-color': '#3b82f6', 'fill-opacity': 0.08 },
            layout: { visibility: 'visible' }
        });
    }
    if (!map.getLayer('kecamatan-line-layer')) {
        map.addLayer({
            id: 'kecamatan-line-layer', source: 'kecamatan', type: 'line',
            paint: { 'line-color': '#3b82f6', 'line-width': 1.5, 'line-dasharray': [3, 2] },
            layout: { visibility: 'visible' }
        });
    }
    if (!map.getLayer('kecamatan-label-layer')) {
        map.addLayer({
            id: 'kecamatan-label-layer', source: 'kecamatan', type: 'symbol',
            layout: {
                'text-field' : ['get', 'nama'],
                'text-font'  : ['Noto Sans Regular', 'Open Sans Regular', 'Arial Unicode MS Regular'],
                'text-size'  : 10,
                'text-anchor': 'center',
                'visibility' : 'visible'
            },
            paint: { 'text-color': '#1e40af', 'text-halo-color': '#ffffff', 'text-halo-width': 1.5 }
        });
    }

    // Pasang listener hanya sekali
    if (!window._kecamatanListenerAttached) {
        window._kecamatanListenerAttached = true;
        map.on('click', 'kecamatan-layer', (event) => {
            const coordinates = event.lngLat;
            const f = event.features[0].properties;
            console.log('FEATURES kecamatan', f);
            const html = `
                <div>
                    <h1 style="font-weight:600;font-size:14px;margin-bottom:8px;border-bottom:1px solid #eee;padding-bottom:6px;">🏙 Informasi Kecamatan</h1>
                    <p style="font-size:12px;color:#555;margin-bottom:3px;">Kecamatan : <b style="color:#222;">${f.nama}</b></p>
                    <p style="font-size:12px;color:#555;margin-bottom:3px;">Kota      : <b style="color:#222;">Semarang</b></p>
                </div>
            `;
            new maplibregl.Popup().setHTML(html).setLngLat(coordinates).addTo(map);
        });
        map.on('mouseenter', 'kecamatan-layer', () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', 'kecamatan-layer', () => { map.getCanvas().style.cursor = ''; });
    }

    document.getElementById('status-kecamatan').textContent = `✅ Kecamatan (${data.features.length} wilayah)`;
}

// ===================================
// JALAN
// ===================================
function loadJalan() {
    const data = dataOffline.jalan;
    console.log('jalanData', data);

    // Tambah source jika belum ada
    if (!map.getSource('jalan')) {
        map.addSource('jalan', { type: 'geojson', data });
    } else {
        map.getSource('jalan').setData(data);
    }

    // Tambah layer jika belum ada
    if (!map.getLayer('jalan-layer')) {
        map.addLayer({
            id: 'jalan-layer', source: 'jalan', type: 'line',
            paint: { 'line-color': '#a96f0b', 'line-width': 2 },
            layout: { visibility: 'visible' }
        });
    }

    // Pasang listener hanya sekali
    if (!window._jalanListenerAttached) {
        window._jalanListenerAttached = true;
        map.on('click', 'jalan-layer', (event) => {
            const coordinates = event.lngLat;
            const f = event.features[0].properties;
            console.log('FEATURES jalan', f);
            const html = `
                <div>
                    <h1 style="font-weight:600;font-size:14px;margin-bottom:8px;">🛣 ${f.nama}</h1>
                    <p style="font-size:12px;color:#555;">Tipe: <b>${f.tipe}</b></p>
                    <p style="font-size:12px;color:#555;">Permukaan: <b>${f.surface}</b></p>
                </div>
            `;
            new maplibregl.Popup().setHTML(html).setLngLat(coordinates).addTo(map);
        });
        map.on('mouseenter', 'jalan-layer', () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', 'jalan-layer', () => { map.getCanvas().style.cursor = ''; });
    }

    document.getElementById('status-jalan').textContent = `✅ Jalan (${data.features.length} segmen)`;
}

// ===================================
// SEMUA FASILITAS
// ===================================
function loadSemuaFasilitas(isFirst = false) {
    // Reset _listenerAttached flag saat ganti basemap supaya listener bisa dipasang ulang
    if (!isFirst) {
        Object.values(kategoriConfig).forEach(cfg => { cfg._listenerAttached = false; });
    }
    ['rs', 'puskesmas', 'klinik', 'apotek', 'drg'].forEach(key => {
        const data = dataOffline[key];
        dataFasilitas[key] = data;
        tambahLayerFasilitas(key, data);

        const count = data.features.length;
        const countEl = document.getElementById(`count-${key}`);
        if (countEl) countEl.textContent = `(${count})`;

        const statusEl = document.getElementById(`status-${key}`);
        if (statusEl) statusEl.textContent = `✅ ${kategoriConfig[key].label} (${count} titik)`;

        console.log(`✅ ${key} termuat:`, count);
    });

    // Restore state toggle setelah semua layer selesai dirender
    restoreToggleState();
}

// ===================================
// HELPER: tambah layer fasilitas
// ===================================
function tambahLayerFasilitas(key, data) {
    const cfg = kategoriConfig[key];

    // Tambah source jika belum ada
    if (!map.getSource(cfg.source)) {
        map.addSource(cfg.source, { type: 'geojson', data });
    } else {
        map.getSource(cfg.source).setData(data);
    }

    // Tambah layer jika belum ada (layer selalu hilang setelah style.load)
    if (!map.getLayer(cfg.layer)) {
        map.addLayer({
            id: cfg.layer, source: cfg.source, type: 'circle',
            paint: {
                'circle-color': cfg.warna, 'circle-radius': 6,
                'circle-stroke-width': 1.5, 'circle-stroke-color': '#ffffff'
            },
            layout: { visibility: 'visible' }
        });
    }

    // Event listener dipasang hanya jika belum ada (cegah duplikasi saat ganti basemap)
    if (!cfg._listenerAttached) {
        cfg._listenerAttached = true;
        map.on('click', cfg.layer, (event) => {
        const coordinates = event.lngLat;
        const f = event.features[0].properties;
        console.log(`FEATURES ${key}`, f);

        const isRS = key === 'rs';
        const html = isRS ? `
            <div>
                <h1 style="font-weight:600;font-size:14px;margin-bottom:8px;border-bottom:1px solid #eee;padding-bottom:6px;">${cfg.icon} ${f.nama}</h1>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Tipe    : <b style="color:#222;">${f.tipe}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Kelas   : <b style="color:#222;">${f.kelas}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Layanan : <b style="color:#222;">${f.layanan}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Alamat  : <b style="color:#222;">${f.alamat}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Telepon : <b style="color:#222;">${f.telepon}</b></p>
            </div>
        ` : `
            <div>
                <h1 style="font-weight:600;font-size:14px;margin-bottom:8px;border-bottom:1px solid #eee;padding-bottom:6px;">${cfg.icon} ${f.nama}</h1>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Kategori : <b style="color:#222;">${cfg.label}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Alamat   : <b style="color:#222;">${f.alamat}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Telepon  : <b style="color:#222;">${f.telepon}</b></p>
                <p style="font-size:12px;color:#555;margin-bottom:3px;">Operator : <b style="color:#222;">${f.operator}</b></p>
            </div>
        `;
        new maplibregl.Popup().setHTML(html).setLngLat(coordinates).addTo(map);
    });

        map.on('mouseenter', cfg.layer, () => { map.getCanvas().style.cursor = 'pointer'; });
        map.on('mouseleave', cfg.layer, () => { map.getCanvas().style.cursor = ''; });
    } // end if !_listenerAttached
}

