// Simpan semua data layer yang perlu di-restore setelah setStyle
const layerDataBackup = [
    { key: 'rs',        type: 'circle' },
    { key: 'puskesmas', type: 'circle' },
    { key: 'klinik',    type: 'circle' },
    { key: 'apotek',    type: 'circle' },
    { key: 'drg',       type: 'circle' },
];

function gantiBasemap(styleUrl) {
    // 1. Catat visibility state sebelum ganti (sudah ada di toggleState)
    console.log('Ganti basemap:', styleUrl);

    // 2. setStyle - ini akan reset semua layer
    map.setStyle(styleUrl);

    // 3. Setelah style selesai load, restore semua layer data
    map.once('style.load', () => {
        console.log('style.load setelah ganti basemap - restore layer data...');

        // Handle sprite yang mungkin gagal load
        map.on('styleimagemissing', (e) => {
            const empty = { width: 1, height: 1, data: new Uint8Array(4) };
            if (!map.hasImage(e.id)) map.addImage(e.id, empty);
        });

        // Restore semua layer data
        loadKecamatan();
        loadJalan();

        // Reset listener flags supaya bisa dipasang ulang
        window._kecamatanListenerAttached = false;
        window._jalanListenerAttached     = false;
        Object.values(kategoriConfig).forEach(cfg => { cfg._listenerAttached = false; });

        loadSemuaFasilitas(false);
    });
}

window.updateStyleToStreet    = () => { gantiBasemap(basemapStreet); };
window.updateStyleToDark      = () => { gantiBasemap(basemapDark); };
window.updateStyleToSatellite = () => { gantiBasemap(basemapSatellite); };

// ===================================
// TOGGLE LAYER
// ===================================
window.toggleLayer = (layerId, btnId) => {
    if (!map.getLayer(layerId)) return;
    const vis  = map.getLayoutProperty(layerId, 'visibility');
    const next = vis === 'visible' ? 'none' : 'visible';
    console.log('visibility', layerId, vis);
    console.log('nextState', layerId, next);
    map.setLayoutProperty(layerId, 'visibility', next);

    // Simpan state ke toggleState supaya ter-restore saat ganti basemap
    if (toggleState.hasOwnProperty(layerId)) toggleState[layerId] = next;

    const btn = document.getElementById(btnId);
    if (btn) {
        btn.textContent = next === 'visible' ? '👁' : '🚫';
        btn.classList.toggle('off', next === 'none');
    }
};

window.toggleLayerKecamatan = () => {
    const layerId = 'kecamatan-layer';
    if (!map.getLayer(layerId)) return;
    const vis  = map.getLayoutProperty(layerId, 'visibility');
    const next = vis === 'visible' ? 'none' : 'visible';
    console.log('visibility kecamatan', vis);
    console.log('nextState kecamatan', next);
    ['kecamatan-layer', 'kecamatan-line-layer', 'kecamatan-label-layer'].forEach(id => {
        if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', next);
    });
    // Simpan state kecamatan ke toggleState
    toggleState['kecamatan-layer'] = next;

    const btn = document.getElementById('btn-kecamatan');
    if (btn) {
        btn.textContent = next === 'visible' ? '👁' : '🚫';
        btn.classList.toggle('off', next === 'none');
    }
};

