window.jalankanBuffer = () => {
    const key    = document.getElementById('buffer-kategori').value;
    const radius = parseInt(document.getElementById('input-buffer').value);
    const data   = dataFasilitas[key];
    const cfg    = kategoriConfig[key];

    if (!data || data.features.length === 0) { alert(`Data ${cfg.label} kosong.`); return; }
    if (isNaN(radius) || radius <= 0) return;

    document.getElementById('label-buffer').textContent = `${radius} m (${cfg.label})`;

    const bufferData = turf.buffer(data, radius, { units: 'meters' });
    console.log('bufferData', bufferData);

    if (map.getSource('buffer')) {
        map.getSource('buffer').setData(bufferData);
        map.setPaintProperty('buffer-layer', 'fill-color', cfg.warna);
    } else {
        map.addSource('buffer', { type: 'geojson', data: bufferData });
        map.addLayer({
            id: 'buffer-layer', source: 'buffer', type: 'fill',
            paint: { 'fill-color': cfg.warna, 'fill-opacity': 0.2 }
        });
    }
};

window.hapusBuffer = () => {
    if (map.getLayer('buffer-layer')) map.removeLayer('buffer-layer');
    if (map.getSource('buffer'))      map.removeSource('buffer');
    document.getElementById('label-buffer').textContent = '-';
};


// ===================================
// CEK LOKASI DALAM SEMARANG
// Bounding box Kota Semarang:
// Lng: 110.27 - 110.51 | Lat: -7.17 - -6.93
// ===================================
function cekDalamSemarang(lng, lat) {
    const batas = {
        lngMin: 110.27,
        lngMax: 110.51,
        latMin: -7.17,
        latMax: -6.93,
    };
    return lng >= batas.lngMin && lng <= batas.lngMax &&
           lat >= batas.latMin && lat <= batas.latMax;
}

