// Helper: buat elemen marker dan pasang event drag
function buatMarkerDraggable(lng, lat) {
    if (markerUser) markerUser.remove();

    const el = document.createElement('div');
    el.style.cssText = `
        width: 20px; height: 20px; background: #ba3333;
        border: 3px solid #ffffff; border-radius: 50%;
        box-shadow: 0 0 0 4px rgba(186,51,51,0.3);
        cursor: grab;
    `;
    el.title = 'Geser untuk pindahkan lokasi';

    // Marker dibuat draggable: true supaya bisa digeser
    markerUser = new maplibregl.Marker({ element: el, draggable: true })
        .setLngLat([lng, lat])
        .addTo(map);

    // Event saat marker mulai digeser
    markerUser.on('dragstart', () => {
        el.style.cursor = 'grabbing';
        console.log('Marker mulai digeser');
    });

    // Event saat marker selesai digeser - update koordinat lokasiUser
    markerUser.on('dragend', () => {
        el.style.cursor = 'grab';
        const newPos = markerUser.getLngLat();
        const newLng = newPos.lng;
        const newLat = newPos.lat;

        // Update variabel global lokasiUser dengan posisi baru
        lokasiUser = { lng: newLng, lat: newLat };
        console.log('LOKASI USER diupdate (drag):', lokasiUser);

        // Cek apakah lokasi baru masih dalam wilayah Semarang
        if (!cekDalamSemarang(newLng, newLat)) {
            tampilkanNotifikasiLuar();
        }

        // Update info di sidebar
        document.getElementById('teks-lokasi').innerHTML = `
            📍 Lokasi diperbarui (drag)!<br>
            Lng: ${newLng.toFixed(5)}<br>
            Lat: ${newLat.toFixed(5)}<br>
            <span style="color:#94a3b8;font-size:10px;">Geser marker untuk ubah posisi</span>
        `;
        document.getElementById('info-lokasi').classList.add('active');
        document.getElementById('status-lokasi').textContent = `✅ Lokasi: ${newLat.toFixed(4)}, ${newLng.toFixed(4)}`;
    });
}

window.laporkanLokasi = () => {
    if (!navigator.geolocation) { alert('Browser kamu tidak mendukung Geolocation.'); return; }

    const btn = document.getElementById('button-lokasi');
    btn.textContent = '⏳ Mendapatkan lokasi...';
    btn.disabled = true;

    navigator.geolocation.getCurrentPosition(
        (position) => {
            const lng     = position.coords.longitude;
            const lat     = position.coords.latitude;
            const akurasi = Math.round(position.coords.accuracy);

            lokasiUser = { lng, lat };
            console.log('LOKASI USER', lokasiUser);

            // Cek apakah lokasi user berada dalam wilayah Semarang
            if (!cekDalamSemarang(lng, lat)) {
                tampilkanNotifikasiLuar();
            }

            // Buat marker yang bisa digeser
            buatMarkerDraggable(lng, lat);

            map.flyTo({ center: [lng, lat], zoom: 14, speed: 1.5, essential: true });

            document.getElementById('teks-lokasi').innerHTML = `
                📍 Lokasi ditemukan!<br>
                Lng: ${lng.toFixed(5)}<br>
                Lat: ${lat.toFixed(5)}<br>
                Akurasi: ±${akurasi} meter<br>
                <span style="color:#94a3b8;font-size:10px;">💡 Geser marker untuk ubah posisi</span>
            `;
            document.getElementById('info-lokasi').classList.add('active');
            btn.textContent = '✅ Lokasi Dilaporkan';
            btn.disabled = false;
            document.getElementById('status-lokasi').textContent = `✅ Lokasi: ${lat.toFixed(4)}, ${lng.toFixed(4)}`;

            console.log('Lokasi berhasil didapat:', lng, lat);
        },
        (error) => {
            console.log('Error geolocation', error);
            btn.textContent = '📍 Laporkan Lokasi Saya';
            btn.disabled = false;
            alert('Gagal mendapatkan lokasi. Pastikan kamu mengizinkan akses lokasi di browser.');
        }
    );
};

