// CARI FASILITAS TERDEKAT
// ===================================
window.cariTerdekat = () => {
    if (!lokasiUser) { alert('Laporkan lokasi kamu dulu!'); return; }

    const key    = document.getElementById('kategori-terdekat').value;
    const data   = dataFasilitas[key];
    const cfg    = kategoriConfig[key];
    const jumlah = parseInt(document.getElementById('jumlah-terdekat').value);

    if (!data || data.features.length === 0) { alert(`Data ${cfg.label} kosong.`); return; }

    const pointUser = turf.point([lokasiUser.lng, lokasiUser.lat]);
    console.log('POINT USER', pointUser);

    // Hitung jarak ke semua fasilitas menggunakan turf.distance
    const hasilJarak = data.features.map(element => {
        const lng    = element.geometry.coordinates[0];
        const lat    = element.geometry.coordinates[1];
        const pointF = turf.point([lng, lat]);
        const jarak  = turf.distance(pointUser, pointF, { units: 'kilometers' });

        console.log(`Jarak ke ${element.properties.nama}: ${jarak} km`);

        return { nama: element.properties.nama, alamat: element.properties.alamat, jarak, lng, lat };
    });

    hasilJarak.sort((a, b) => a.jarak - b.jarak);
    const topN = hasilJarak.slice(0, jumlah);
    console.log('HASIL TERDEKAT', topN);

    let resultString = '';
    topN.forEach(f => {
        const jarakTampil = f.jarak < 1
            ? `${Math.round(f.jarak * 1000)} m`
            : `${f.jarak.toFixed(2)} km`;

        resultString += `<li class="hasil-item" onclick="flyToFasilitas(${f.lng}, ${f.lat}, '${f.nama.replace(/'/g, "\\'")}', '${key}')">
            <div>${cfg.icon} ${f.nama}</div>
            <div style="font-size:10px;color:#94a3b8;margin-top:2px;">${cfg.label} • 📍 ${jarakTampil}</div>
        </li>`;
    });

    document.getElementById('hasil-terdekat').innerHTML = resultString;
    document.getElementById('count-terdekat').textContent = `(${topN.length})`;
};

// ===================================
// ISOCHRONE - Valhalla API (realistis, mengikuti jaringan jalan)
// Endpoint publik gratis, tidak perlu API key
// Fallback otomatis ke buffer jika Valhalla tidak bisa diakses
// ===================================
document.getElementById('button-run').addEventListener('click', () => executeIsochrone());

// Mapping mode transportasi ke profil Valhalla
const valhallaProfile = {
    motorcycle: 'motorcycle',
    car       : 'auto',
};

async function executeIsochrone() {
    if (!lokasiUser) { alert('Laporkan lokasi kamu dulu!'); return; }

    const key          = document.getElementById('isochrone-kategori').value;
    const data         = dataFasilitas[key];
    const cfg          = kategoriConfig[key];
    const transportasi = document.getElementById('transportasi').value;
    const waktuMenit   = parseInt(document.getElementById('waktu').value);

    if (!data || data.features.length === 0) { alert(`Data ${cfg.label} kosong.`); return; }

    const btn = document.getElementById('button-run');
    btn.textContent = '⏳ Memuat isochrone...';
    btn.disabled = true;

    try {
        // Profil Valhalla sesuai mode transportasi
        const profile = valhallaProfile[transportasi] || 'auto';

        // Request body ke Valhalla
        const requestBody = {
            locations: [{ lon: lokasiUser.lng, lat: lokasiUser.lat }],
            costing  : profile,
            contours : [{ time: waktuMenit, color: cfg.warna.replace('#', '') }],
            polygons : true,
            denoise  : 1,
        };

        console.log('Valhalla request:', requestBody);
        console.log(`Isochrone: profile=${profile}, waktu=${waktuMenit} menit`);

        // Valhalla public endpoint - gratis, tanpa API key
        const valhallaUrl = `https://valhalla1.openstreetmap.de/isochrone?json=${encodeURIComponent(JSON.stringify(requestBody))}`;
        const response    = await fetch(valhallaUrl);

        if (!response.ok) throw new Error(`Valhalla HTTP ${response.status}`);

        const isochroneData = await response.json();
        console.log('HASIL ISOCHRONE VALHALLA', isochroneData);

        renderIsochrone(isochroneData, data, cfg, key);

    } catch(e) {
        console.error('Valhalla error:', e);
        console.warn('Fallback ke simulasi buffer...');

        // Fallback ke buffer sederhana jika Valhalla gagal
        executeFallbackBuffer(key, data, cfg, transportasi, waktuMenit);
    } finally {
        btn.textContent = 'Jalankan Analisis';
        btn.disabled = false;
    }
}

// Render hasil isochrone ke peta dan cek fasilitas di dalamnya
function renderIsochrone(geojsonIsochrone, data, cfg, key, isFallback = false) {
    // Hapus isochrone lama
    if (map.getLayer('isochrone-fill-layer')) map.removeLayer('isochrone-fill-layer');
    if (map.getLayer('isochrone-line-layer')) map.removeLayer('isochrone-line-layer');
    if (map.getSource('isochrone'))           map.removeSource('isochrone');

    // Tambah source dan 2 layer: fill + outline
    map.addSource('isochrone', { type: 'geojson', data: geojsonIsochrone });
    map.addLayer({
        id: 'isochrone-fill-layer', source: 'isochrone', type: 'fill',
        paint: { 'fill-color': cfg.warna, 'fill-opacity': 0.2 }
    });
    map.addLayer({
        id: 'isochrone-line-layer', source: 'isochrone', type: 'line',
        paint: { 'line-color': cfg.warna, 'line-width': 2, 'line-opacity': 0.9 }
    });

    // Cek fasilitas dalam polygon isochrone
    let resultString = '';
    let jumlah       = 0;

    const isoFeature = geojsonIsochrone.features ? geojsonIsochrone.features[0] : geojsonIsochrone;
    if (!isoFeature) return;

    const poly = isoFeature.geometry.type === 'Polygon'
        ? turf.polygon(isoFeature.geometry.coordinates)
        : turf.multiPolygon(isoFeature.geometry.coordinates);

    for (let i = 0; i < data.features.length; i++) {
        const element = data.features[i];
        const lng     = element.geometry.coordinates[0];
        const lat     = element.geometry.coordinates[1];
        const pt      = turf.point([lng, lat]);

        console.log('DATA FASILITAS', element);
        console.log('DALAM ISOCHRONE?', turf.booleanPointInPolygon(pt, poly));

        if (turf.booleanPointInPolygon(pt, poly)) {
            jumlah++;
            const namaEscaped = element.properties.nama.replace(/'/g, "\'");
            resultString += `<li class="hasil-item" onclick="flyToFasilitas(${lng}, ${lat}, '${namaEscaped}', '${key}')">${cfg.icon} ${element.properties.nama}</li>`;
        }
    }

    console.log('HASIL STRING', resultString);

    document.getElementById('hasil').innerHTML = resultString
        || `<li style="font-size:11px;color:#94a3b8;padding:8px;">Tidak ada ${cfg.label} dalam jangkauan</li>`;
    document.getElementById('count-hasil').textContent = isFallback ? `(${jumlah}) *simulasi` : `(${jumlah})`;
    document.getElementById('hasil-wrapper').style.display = 'block';
}

// Fallback: buffer sederhana jika Valhalla tidak bisa diakses
function executeFallbackBuffer(key, data, cfg, transportasi, waktuMenit) {
    const kecepatan      = kecepatanTransportasi[transportasi] || 80;
    const radiusEstimasi = kecepatan * waktuMenit;

    console.log(`Fallback buffer: ${radiusEstimasi}m`);

    const pointUser       = turf.point([lokasiUser.lng, lokasiUser.lat]);
    const isochoneGeojson = turf.buffer(pointUser, radiusEstimasi, { units: 'meters' });

    renderIsochrone(
        { type: 'FeatureCollection', features: [isochoneGeojson] },
        data, cfg, key, true
    );
}

window.hapusIsochrone = () => {
    if (map.getLayer('isochrone-fill-layer')) map.removeLayer('isochrone-fill-layer');
    if (map.getLayer('isochrone-line-layer')) map.removeLayer('isochrone-line-layer');
    if (map.getSource('isochrone'))           map.removeSource('isochrone');
    document.getElementById('hasil-wrapper').style.display = 'none';
    document.getElementById('hasil').innerHTML = '';
    document.getElementById('count-hasil').textContent = '';
};


